function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is an integer from 1 to 10^5.';
  if (!Number.isInteger(target) || target < 1 || target > 1000000000) return 'target is an integer from 1 to 10^9.';
  return null;
}

