function minSizeSubarray(nums, target) {
  const n = nums.length;
  const total = nums.reduce((sum, value) => sum + value, 0);
  const cycles = Math.floor(target / total);
  const rest = target % total;
  if (rest === 0) {
    return cycles * n;
  }

  let best = Infinity;
  let windowSum = 0;
  let left = 0;
  for (let right = 0; right < 2 * n; right++) {
    windowSum += nums[right % n];
    while (windowSum > rest) {
      windowSum -= nums[left % n];
      left++;
    }
    if (windowSum === rest) {
      best = Math.min(best, right - left + 1);
    }
  }
  return best === Infinity ? -1 : cycles * n + best;
}

