function minSizeSubarray(nums, target) {
  // Any subarray is some start, some whole copies, and a partial piece of 0..n-1 elements.
  const n = nums.length;
  let total = 0;
  for (const value of nums) total += value;
  let answer = -1;
  for (let start = 0; start < n; start++) {
    let piece = 0;
    for (let extra = 0; extra < n; extra++) {
      if (extra > 0) piece += nums[(start + extra - 1) % n];
      const remaining = target - piece;
      if (remaining < 0 || remaining % total !== 0) continue;
      const length = (remaining / total) * n + extra;
      if (length > 0 && (answer === -1 || length < answer)) answer = length;
    }
  }
  return answer;
}

