function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? 2000 : pick(1, 6);
  const high = large ? (rand() < 0.5 ? 3 : 100000) : (rand() < 0.5 ? 3 : 9);
  const nums = Array.from({ length: n }, () => pick(1, high));
  const total = nums.reduce((a, b) => a + b, 0);
  if (rand() < 0.3) return [nums, large ? pick(1, 1000000000) : pick(1, 40)];
  // Otherwise aim at a reachable sum: whole copies plus one wrapped window.
  const maxCycles = large ? Math.floor(1000000000 / total) - 1 : 3;
  const cycles = pick(0, maxCycles);
  const start = pick(0, n - 1);
  const length = pick(cycles === 0 ? 1 : 0, n - 1);
  let window = 0;
  for (let i = 0; i < length; i++) window += nums[(start + i) % n];
  return [nums, cycles * total + window];
}
